      SUBROUTINE FOCUSCC     FIRST-ORDER TRANSFER MATRIX FOR FOCUSING ELEMENTC     (QUADRUPOLE, BENDING MAGNET, OR PLASMA LENS)CC     LIST OF COMMON BLOCKSC      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM5A.CIN'      INCLUDE 'ELM5B.CIN'      INCLUDE 'R.CIN'CC     LOCAL VARIABLESC      REAL  KL, Y, YICC-----------------------------------------------------------------C      J = JQUAD      KL = SQRT( ABS(KQ2)) * L      IF (KQ2 .GE. 0.0) THEN        CS = COS(KL)        SN = SIN(KL)      ELSE        Y = EXP(KL)        YI = 1.0/Y        CS = 0.5*(Y + YI)        SN = 0.5*(Y - YI)      ENDIF      R(J+1,J+1) = CS      R(J,J) = CS      IF (KL .NE. 0.) THEN        R(J,J+1) = L*SN/KL      ELSE        R(J,J+1) = L      ENDIF      R(J+1,J) =  - KQ2 * R(J,J+1)      RETURN      END